def count_pairs_with_gap(nums, k):
    seen = {}
    count = 0
    for x in nums:
        count += seen.get(x - k, 0)
        if k:
            count += seen.get(x + k, 0)
        seen[x] = seen.get(x, 0) + 1
    return count
